import fs from 'node:fs/promises';
import { transform } from 'esbuild';
const root = new URL('./', import.meta.url);
const files = ['src/engine.js', 'src/icons.js', 'src/bridge.js'];
const source = (await Promise.all(files.map(file => fs.readFile(new URL(file, root), 'utf8')))).join('\n');
const { code } = await transform(source, { format: 'esm', minify: true, target: 'es2020' });
await fs.writeFile(new URL('../../client/src/components/icons/kubai-runtime.js', root),
  '// Generated by design-assets/workbench-icons/build.mjs.\n' +
  '// Copyright (c) 2026 Kubai087. Engine: Kubai Icons License; library icons: MIT.\n' +
  '// Licenses and editable sources: design-assets/workbench-icons/.\n' + code);
